import{_ as e,o as t,c as i,aw as l}from"./chunks/framework.DLufY-ao.js";const _=JSON.parse('{"title":"Виды тестирования","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/testing/testing/theory/types.md","filePath":"wiki/dev-commit/testing/testing/theory/types.md"}'),r={name:"wiki/dev-commit/testing/testing/theory/types.md"};function o(h,a,n,s,d,u){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="виды-тестирования" tabindex="-1">Виды тестирования <a class="header-anchor" href="#виды-тестирования" aria-label="Permalink to &quot;Виды тестирования&quot;">​</a></h1><h2 id="виды-тестирования-1" tabindex="-1">Виды тестирования <a class="header-anchor" href="#виды-тестирования-1" aria-label="Permalink to &quot;Виды тестирования&quot;">​</a></h2><h3 id="_1-статическое-тестирование" tabindex="-1">1. Статическое тестирование <a class="header-anchor" href="#_1-статическое-тестирование" aria-label="Permalink to &quot;1. Статическое тестирование&quot;">​</a></h3><ul><li>Программный код не выполняется - анализ программы происходит на основе исходного кода, который вычитывается вручную, либо анализируется специальными инструментами</li></ul><h3 id="_2-динамическое-тестирование" tabindex="-1">2. Динамическое тестирование <a class="header-anchor" href="#_2-динамическое-тестирование" aria-label="Permalink to &quot;2. Динамическое тестирование&quot;">​</a></h3><ul><li>Код исполняется</li></ul><h4 id="классификация" tabindex="-1">Классификация <a class="header-anchor" href="#классификация" aria-label="Permalink to &quot;Классификация&quot;">​</a></h4><ul><li>Тестирование «белого ящика» - разработчик теста имеет доступ к исходному коду программ и может писать код, который связан с библиотеками тестируемого программного обеспечения. Это типично для компонентного тестирования, при котором тестируются только отдельные части системы. Оно обеспечивает то, что компоненты конструкции работоспособны и устойчивы, до определённой степени</li><li>Тестирование «чёрного ящика» - тестировщик имеет доступ к программе только через те же интерфейсы, что и заказчик или пользователь, либо через внешние интерфейсы, позволяющие другому компьютеру либо другому процессу подключиться к системе для тестирования. Например, тестирующий компонент может виртуально нажимать клавиши или кнопки мыши в тестируемой программе с помощью механизма взаимодействия процессов</li><li>Тестирование «серого ящика» - разработчик теста имеет доступ к исходному коду, но при непосредственном выполнении тестов доступ к коду, как правило, не требуется</li></ul><h3 id="_3-регрессионное-тестирование" tabindex="-1">3. Регрессионное тестирование <a class="header-anchor" href="#_3-регрессионное-тестирование" aria-label="Permalink to &quot;3. Регрессионное тестирование&quot;">​</a></h3><ul><li>После внесения изменений в очередную версию программы, регрессионные тесты подтверждают, что сделанные изменения не повлияли на работоспособность остальной функциональности приложения. Регрессионное тестирование может выполняться как вручную, так и средствами автоматизации тестирования</li></ul><hr><h2 id="данные" tabindex="-1">Данные <a class="header-anchor" href="#данные" aria-label="Permalink to &quot;Данные&quot;">​</a></h2><h3 id="виды-тестирования-компонентов" tabindex="-1">Виды тестирования компонентов <a class="header-anchor" href="#виды-тестирования-компонентов" aria-label="Permalink to &quot;Виды тестирования компонентов&quot;">​</a></h3><ul><li>Тестирование при помощи снимков (Snapshot-тестирование)</li><li>Тестирование логики компонентов</li></ul><h3 id="другие-виды-тестирования" tabindex="-1">Другие виды тестирования <a class="header-anchor" href="#другие-виды-тестирования" aria-label="Permalink to &quot;Другие виды тестирования&quot;">​</a></h3><ul><li>Юнит тесты</li><li>Компонентные тесты</li><li>Авто тесты</li><li>Альфа тестирование</li></ul>',16)])])}const m=e(r,[["render",o]]);export{_ as __pageData,m as default};
